func StaleMongoKeysToPrune(rec map[string]any, doc bson.M, targetKey string) []string {
	if doc == nil {
		return nil
	}
	var out []string
	for k := range rec {
		if strings.HasPrefix(k, "_") || k == targetKey ||
			k == "source_field_types" || k == "sourceFieldTypes" {
			continue
		}
		if _, stillPresent := doc[k]; !stillPresent {
			out = append(out, k)
		}
	}
	sort.Strings(out)
	return out
}

